package org.apache.commons.lang3.time;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Calendar;

public class AgentBRT_Lang_21_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        Calendar cal1 = Calendar.getInstance();
        cal1.set(Calendar.HOUR_OF_DAY, 10); // 10 AM
        cal1.set(Calendar.MINUTE, 30);
        cal1.set(Calendar.SECOND, 0);
        cal1.set(Calendar.MILLISECOND, 0);

        Calendar cal2 = Calendar.getInstance();
        cal2.set(Calendar.HOUR_OF_DAY, 22); // 10 PM
        cal2.set(Calendar.MINUTE, 30);
        cal2.set(Calendar.SECOND, 0);
        cal2.set(Calendar.MILLISECOND, 0);

        // The test should fail because the method incorrectly uses Calendar.HOUR
        assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }
}

